public void init()
{
    next init();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        this.args().parmEnum() == MarkupModuleType::Cust)
    {
        PriceComponentCodeGroup.visible(true);
        PriceComponentCodeGroup.enabled(true);
        MarkupAutoTable_PriceComponentCodeName.mandatory(true);
        FormStringControl descriptionControl = this.design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoTable_MarkupAutoTableDescription)) as FormStringControl;
        descriptionControl.mandatory(true);

        HeaderPriceAttributeGroupGroup.visible(true);
        HeaderPriceAttributeGroupGroup.enabled(true);
        LinePriceAttributeGroupGroup.visible(true);
        LinePriceAttributeGroupGroup.enabled(true);
        GUPPricingRuleHeader_PricingGroupDetails.visible(true);
        GUPPricingRuleHeader_PricingGroupDetails.enabled(true);
        GUPPricingRuleLine_PricingGroupDetails.visible(true);
        GUPPricingRuleLine_PricingGroupDetails.enabled(true);
        Grid_MarkupAutoTable_PriceComponentCodeName.visible(true);
        PriceAttributeGroupEdit.visible(true);

        Grid_AccountCode.visible(false);
        Grid_AccountRe.visible(false);
        MarkupAutoTable_AccountCode.visible(false);
        MarkupAutoTable_AccountRelation.visible(false);
        MarkupAutoTable_ItemCode.visible(false);
        MarkupAutoTable_ItemRelation.visible(false);
        this.design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoTable_DlvModeCode)).visible(false);
        MarkupAutoTable_DlvModeRelation.visible(false);
    }
}

[FormControlEventHandler(formControlStr(MarkupAutoSetup, MarkupAutoTable_PriceComponentCodeName), FormControlEventType::Lookup)]
public static void MarkupAutoTable_PriceComponentCodeName_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    SysTableLookup          SysTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tableNum(GUPPriceComponentCode));

    SysTableLookup = SysTableLookup::newParameters(tableNum(GUPPriceComponentCode), _sender);
    SysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Name));
    SysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Description));

    qbds.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::AutoCharges));

    SysTableLookup.parmQuery(query);
    SysTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs ce = _e as FormControlCancelableSuperEventArgs;
    ce.CancelSuperCall();
}
